//! Actual old controls plus complete raw producer; no source/model fabrication.
use crate::*;use std::io;
#[path="../fixtures/native-ui-actions-workspace/fixture.rs"]mod fixture;
#[path="../fixtures/native-ui-actions-workspace/direct.rs"]mod direct;
#[path="../fixtures/original_policies/ui_actions_lineage_original.rs"]mod old_lineage;
#[path="../fixtures/original_policies/ui_actions_params_original.rs"]mod old_params;
#[path="../fixtures/original_policies/ui_actions_enclosing_original.rs"]mod old_enclosing;
struct Control{polls:usize,fail:usize,left:usize}impl key_policy_control::Control for Control{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),io::Error>{self.polls+=1;if self.polls==self.fail{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,n:usize)->Result<(),io::Error>{self.left=self.left.checked_sub(n).ok_or(io::ErrorKind::OutOfMemory)?;Ok(())}fn overflow(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}}
fn work()->Control{Control{polls:0,fail:usize::MAX,left:64*1024*1024}}
#[test]fn actual_original_ui_shared_lineage_params_enclosing_keep_all_lexical_quirks(){for path in ["/obj/a","/mob/living/a","/turf","/area/a","/client/x","/list","/","/datum/capability/a/", "relative/a", "//obj///x"]{assert_eq!(dm::dx::lineage_using(path,&mut work()).unwrap(),old_lineage::lineage(path),"{path}");}for p in ["mob/user, value, key = list(1, 2)","x as num, y as null|text", "...", "a = \"x\\\",y\", z", "list/a, /obj/item/I=null", "q = foo([1,2], {x}), last"]{assert_eq!(dm::dx::param_names_using(p,&mut work()).unwrap(),old_params::param_names(p),"{p}");}for line in ["use(value)","obj.use(value)","use(first, key = value)","use(\"a,b\", value)","use(list(1,2), value)","outer(inner(value), other)","src:use(value)"]{let at=line.find("value").unwrap();let old=old_enclosing::enclosing_call(line,at).map(|v|(v.name,v.index,v.key,v.member));let actual=dm::dx::enclosing_call_using(line,at,&mut work()).unwrap().map(|v|(v.name,v.index,v.key,v.member));assert_eq!(actual,old,"{line}");}}
fn actual<T>(r:Result<T,captured_reactive_reads::Failure>)->io::Error{match r{Err(captured_reactive_reads::Failure::Operational(e))=>e,Err(captured_reactive_reads::Failure::Unsupported(s))=>panic!("unexpected semantic refusal: {s}"),Ok(_)=>panic!("controlled work completed")}}
#[test]fn ui_complete_producer_refuses_first_inner_io_quota_cancel_and_recovers(){let root=std::env::current_dir().unwrap().join("ui-control-root");let files=fixture::files("helpers");let n=std::cell::Cell::new(0);let poll=||{let next=n.get()+1;n.set(next);if next==1450{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};assert_eq!(actual(direct::run(&root,&files,64*1024*1024,None,&poll)).raw_os_error(),Some(1450));assert_eq!(n.get(),1450);assert_eq!(actual(direct::run(&root,&files,128,None,&||Ok(()))).kind(),io::ErrorKind::OutOfMemory);assert_eq!(actual(direct::run(&root,&files,64*1024*1024,None,&||Err(io::Error::from(io::ErrorKind::Interrupted)))).kind(),io::ErrorKind::Interrupted);let out=direct::run(&root,&files,64*1024*1024,None,&||Ok(())).unwrap();assert!(!out.sites().is_empty());for phase in 0..2{assert!(matches!(direct::run(&root,&files,64*1024*1024,Some(phase),&||Ok(())),Err(captured_reactive_reads::Failure::Unsupported(_))));}}
#[test]fn ui_missing_and_bad_dispatcher_never_walk_productive_payloads(){let root=std::env::current_dir().unwrap();for case in ["missing","malformed"]{let out=direct::run(&root,&fixture::files(case),64*1024*1024,None,&||Ok(())).unwrap();assert_eq!(out.sites().len(),usize::from(case=="malformed"));assert_eq!(out.source_text().len(),out.sites().len());assert_eq!(out.notes().len(),usize::from(case=="malformed"));}}
